fn is_non_prime(n: u64) -> bool {
    // Since n >= 2 by assumption,
    // handle the smallest prime case efficiently
    if n == 2 {
        return false;
    }

    // Check divisors from 2 up to sqrt(n)
    // If any divides n, then n is non-prime (composite)
    let limit = (n as f64).sqrt() as u64;
    for k in 2..=limit {
        if n % k == 0 {
            return true; // non-prime found
        }
    }

    // No divisors found => n is prime => return false
    false
}